import { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import { FilterDataAccessor } from 'domain/Filter';
import {
  usePageFilterApplied,
  usePageFilterData,
  usePageFilterManagement,
  usePageFilterStatus,
} from 'hooks';
import { FilterForm } from 'models/Filters';

import {
  buildCommercialDrillDownClearPatch,
  type CommercialDrillDownDimensionKey,
  hasCommercialSpecificFilterValue,
} from '../../commercialResultsClearDrillDown';
import { COMMERCIAL_RESULTS_PAGE_NAME } from '../../constants';
import { CR_WATERFALL_RESET_EVENT } from '../useCommercialResultsWaterfallFilterSync/useCommercialResultsWaterfallFilterSync';

type CommercialDrillKey = CommercialDrillDownDimensionKey;

const GOLDEN_PATH_ORDER: readonly CommercialDrillKey[] = [
  'region',
  'channel',
  'brands',
  'sub_brands',
  'pack_type',
  'sku',
];

const EMPTY_VALUES = new Set(['', 'ALL', 'All']);

export const useCommercialResultsBreadcrumb = () => {
  const { applied } = usePageFilterApplied(COMMERCIAL_RESULTS_PAGE_NAME);
  const { defaults, dataFilters } = usePageFilterData(
    COMMERCIAL_RESULTS_PAGE_NAME,
  );

  const { isLoading } = usePageFilterStatus(COMMERCIAL_RESULTS_PAGE_NAME);
  const { updateAllForm, apply } = usePageFilterManagement(
    COMMERCIAL_RESULTS_PAGE_NAME,
  );

  const appliedRef = useRef(applied);
  appliedRef.current = applied;

  const defaultsRef = useRef(defaults);
  defaultsRef.current = defaults;

  const rootLabel = String(
    FilterDataAccessor.getInstance().getCountry(dataFilters, applied)?.label ??
      '',
  );

  // Chronological selection order: reads `nav_cr_order` on reload, or filter_* URL params
  // when absent (cross-page navigation before Redux applies filters).
  const [navigationOrder, setNavigationOrder] = useState<CommercialDrillKey[]>(
    () => {
      const params = new URLSearchParams(globalThis.location.search);
      const raw = params.get('nav_cr_order');
      if (raw) {
        return raw
          .split(',')
          .filter((k): k is CommercialDrillKey =>
            (GOLDEN_PATH_ORDER as readonly string[]).includes(k),
          );
      }
      return GOLDEN_PATH_ORDER.filter((key) => {
        const value = params.get(`filter_${key}`);
        return value !== null && !EMPTY_VALUES.has(value);
      });
    },
  );

  // Effect 1 — diff applied vs. previous applied to keep navigationOrder in sync.
  const prevAppliedRef = useRef<FilterForm | undefined>(undefined);
  useEffect(() => {
    const prev = prevAppliedRef.current;
    prevAppliedRef.current = applied;

    if (!prev) {
      // First render: keep entries with a specific value in `applied` or URL params
      // (`applied` may still be "All" during cross-page navigation).
      const params = new URLSearchParams(globalThis.location.search);
      setNavigationOrder((prevOrder) => {
        const cleaned = prevOrder.filter((key) => {
          if (
            hasCommercialSpecificFilterValue(
              applied?.[key as keyof typeof applied],
            )
          ) {
            return true;
          }
          const urlValue = params.get(`filter_${key}`);
          return urlValue !== null && !EMPTY_VALUES.has(urlValue);
        });
        // Preserve reference when unchanged — avoids re-render and redundant URL write in Effect 2.
        return cleaned.length === prevOrder.length ? prevOrder : cleaned;
      });
      return;
    }

    setNavigationOrder((prevOrder) => {
      let order = [...prevOrder];
      let changed = false;
      for (const key of GOLDEN_PATH_ORDER) {
        const wasSpecific = hasCommercialSpecificFilterValue(prev?.[key]);
        const isSpecific = hasCommercialSpecificFilterValue(applied?.[key]);
        if (!wasSpecific && isSpecific && !order.includes(key)) {
          order = [...order, key];
          changed = true;
        } else if (!isSpecific && order.includes(key)) {
          // Remove when no longer specific: reset to "All" or stale nav_cr_order after reload.
          order = order.filter((k) => k !== key);
          changed = true;
        }
      }
      return changed ? order : prevOrder;
    });
  }, [applied]);

  useEffect(() => {
    const handleFilterReset = () => {
      setNavigationOrder([]);
    };

    globalThis.addEventListener(CR_WATERFALL_RESET_EVENT, handleFilterReset);
    return () =>
      globalThis.removeEventListener(
        CR_WATERFALL_RESET_EVENT,
        handleFilterReset,
      );
  }, []);

  // Effect 2 — persists navigationOrder to URL as `nav_cr_order`. Skipped on first mount.
  const isFirstNavigationMount = useRef(true);

  useEffect(() => {
    if (isFirstNavigationMount.current) {
      isFirstNavigationMount.current = false;
      return;
    }
    const params = new URLSearchParams(globalThis.location.search);
    if (navigationOrder.length > 0) {
      params.set('nav_cr_order', navigationOrder.join(','));
    } else {
      params.delete('nav_cr_order');
    }
    globalThis.history.replaceState({}, '', `?${params.toString()}`);
  }, [navigationOrder]);

  // path is ordered chronologically (by selection sequence)
  const { path, pathWithKeys } = useMemo(() => {
    const chips: string[] = [];
    const keyed: { label: string; key: CommercialDrillKey }[] = [];

    for (const key of navigationOrder) {
      const value = applied?.[key as keyof typeof applied];
      if (hasCommercialSpecificFilterValue(value)) {
        chips.push(String(value));
        keyed.push({ label: String(value), key });
      }
    }

    return { path: chips, pathWithKeys: keyed };
  }, [applied, navigationOrder]);

  const pathWithKeysRef = useRef(pathWithKeys);
  pathWithKeysRef.current = pathWithKeys;

  // Navigate back to a breadcrumb step. pathIndex >= 0 keeps chips[0..index]; < 0 clears all.
  // Path is chronological — keysToClean is the complement of keysToKeep, not a GOLDEN_PATH slice.
  const goToStep = useCallback(
    (pathIndex: number) => {
      const chips = pathWithKeysRef.current;

      const keysToKeep = new Set(
        pathIndex >= 0 ? chips.slice(0, pathIndex + 1).map((c) => c.key) : [],
      );
      const keysToClean = GOLDEN_PATH_ORDER.filter(
        (key) => !keysToKeep.has(key),
      );

      if (keysToClean.length === 0) return;

      const clearedFilters = buildCommercialDrillDownClearPatch(
        defaultsRef.current,
        keysToClean,
      );

      updateAllForm({ ...appliedRef.current, ...clearedFilters });
      apply();
    },
    [apply, updateAllForm],
  );

  return { rootLabel, path, goToStep, isLoading };
};
